// Zoekt de lijst deployments in de MCP-uitvoer (structuredContent of JSON in tekst).
function* walk(v, d = 0) {
  if (d > 12 || v == null) return;
  if (typeof v === 'string') { const s = v.trim(); if (s.startsWith('{') || s.startsWith('[')) { try { yield* walk(JSON.parse(s), d + 1); } catch (e) {} } return; }
  if (Array.isArray(v)) { for (const c of v) yield* walk(c, d + 1); return; }
  if (typeof v === 'object') { yield v; for (const k of Object.keys(v)) yield* walk(v[k], d + 1); }
}
let list = [];
for (const o of walk($input.all().map(i => i.json))) { if (Array.isArray(o.deployments)) { list = o.deployments; break; } }
return list
  .filter(d => d.verlopen && ['applied', 'apply_failed'].includes(d.status) && d.aanvrager_email)
  .map(d => ({ json: {
    to: d.aanvrager_email,
    subject: `Deployment verlopen: ${d.deployment_id}`,
    text: `De einddatum van deployment "${d.naam}" (${d.deployment_id}, ${d.vms} VM's) is voorbij (${d.ends_at}).\n\n` +
          `Vraag de infra-agent in de chat: "verwijder deployment ${d.deployment_id}". ` +
          `Na goedkeuring worden de VM's verwijderd. Wil je ze langer houden, vraag de agent dan de einddatum aan te passen.`,
  } }));
